					type: "text_end",
					contentIndex: 0,
					content: response,
					partial: partialMessage,
				});
				stream.end({
					...defaultFields,
					role: "assistant",
					content: [{ type: "text", text: response }],
					stopReason: "stop",
					timestamp: Date.now(),
				} as AssistantMessage);
			} catch (error) {
				const message = error instanceof Error ? error.message : String(error);
				// Without this the failure is invisible: the UI shows the generic
